// Zentrale Konfiguration - hier Modell/Endpunkte/Gewichte aendern.
const inp = $input.first();
return [{
  json: { ...inp.json, config: {
    // LLM (LM Studio, OpenAI-kompatibel). Standard: qwen3-235b-a22b-2507 (MLX, 512GB).
    // Schnellere Alternativen: 'nemotron-cascade-2-30b-a3b' oder 'openai/gpt-oss-20b'
    llm_url:   'http://100.120.133.22:1234/v1/chat/completions',
    llm_model: 'qwen/qwen3-235b-a22b-2507',
    whisper_url:   'http://100.120.133.22:8000/transcribe',
    gotenberg_url: 'http://gotenberg:3000/forms/chromium/convert/html',
    // Bild-PDF-Fallback (nicht maschinenlesbare PDFs): Rasterung + Vision-OCR
    rasterize_url: 'http://100.120.133.22:5001/pdf2png',
    vlm_model: 'qwen/qwen3-vl-30b',
    temperature: 0,
    thresholds: { audio_min_sek: 120, pdf_max_mb: 50, audio_exts: ['mp3','wav','m4a','ogg'], pdf_min_chars: 200 },
    // Aggregationsgewichte N08a (Summe = 1.0)
    gewichte: { N02: 0.20, N03: 0.15, N05: 0.30, N06: 0.20, N07: 0.15 }
  } },
  binary: inp.binary
}];

// Bringt die Form-Uploads auf feste Binary-Keys: 'audio' und 'pdf_0','pdf_1',...
const inp = $input.first();
const bin = inp.binary || {};
const out = {};
let audioKey = null;
const pdfKeys = [];
for (const [k, v] of Object.entries(bin)) {
  const mt = (v.mimeType || '').toLowerCase();
  const fn = (v.fileName || '').toLowerCase();
  if (!audioKey && (mt.startsWith('audio') || /\.(mp3|wav|m4a|ogg)$/.test(fn))) audioKey = k;
  else if (mt.includes('pdf') || fn.endsWith('.pdf')) pdfKeys.push(k);
}
if (audioKey) out.audio = bin[audioKey];
pdfKeys.forEach((k, i) => { out['pdf_' + i] = bin[k]; });
return [{ json: { ...inp.json, _pdf_count: pdfKeys.length }, binary: out }];

// Regelbasierte Eingangspruefung (kein LLM). Setzt json.freigabe + json.fehlerreport.
const inp = $input.first();
const cfg = $('Config').first().json.config;
const t = cfg.thresholds;
const bin = inp.binary || {};
const errors = [];
const audio = bin.audio;
const pdfCount = Number(inp.json._pdf_count || 0);
if (!audio) errors.push('Keine Audiodatei erkannt.');
else {
  const fn = (audio.fileName || '').toLowerCase();
  const okExt = t.audio_exts.some(e => fn.endsWith('.' + e)) || (audio.mimeType || '').startsWith('audio');
  if (!okExt) errors.push('Audioformat nicht unterstuetzt (erlaubt: ' + t.audio_exts.join(', ') + ').');
}
if (pdfCount < 1) errors.push('Kein Kundendokument (PDF) erkannt.');
const freigabe = errors.length === 0;
return [{ json: { ...inp.json, freigabe, fehlerreport: errors,
  hinweis_dauer: 'Audiodauer >= ' + (t.audio_min_sek/60) + ' Min und PDF-Maschinenlesbarkeit werden nach N00/N00b geprueft.' },
  binary: bin }];

// Negativfall JC-00: Workflow startet die Analyse NICHT, liefert konkrete Korrekturhinweise.
const j = $input.first().json;
return [{ json: { status: 'abgelehnt', unternehmen: j.Unternehmen || '',
  meldung: 'Eingangspruefung nicht bestanden. Bitte korrigieren und erneut hochladen.',
  korrekturhinweise: j.fehlerreport || [] } }];

// Ein Item pro hochgeladenem PDF (binary 'pdf').
const inp = $input.first();
const bin = inp.binary || {};
const items = [];
let idx = 0;
for (const [k, v] of Object.entries(bin)) {
  if (k.indexOf('pdf_') === 0) {
    items.push({ json: { pdf_index: idx, pdf_name: v.fileName || ('Dokument_' + (idx + 1)) }, binary: { pdf: v } });
    idx++;
  }
}
if (!items.length) items.push({ json: { pdf_index: 0, pdf_name: '(kein PDF)' }, binary: {} });
return items;

// Pro PDF: Textmenge bewerten, Original-PDF-Binary wiederherstellen, OCR-Bedarf markieren.
const src = $('PDFs auftrennen').item;
const cfg = $('Config').first().json.config;
const text = String($json.text || $json.data || '');
return { json: {
  pdf_index: src.json.pdf_index, pdf_name: src.json.pdf_name,
  text, text_len: text.trim().length,
  needs_ocr: text.trim().length < cfg.thresholds.pdf_min_chars
}, binary: src.binary };

// Baut pro Bildseite einen Vision-Request (qwen3-vl) zur woertlichen Textextraktion.
const cfg = $('Config').first().json.config;
const sources = $('PDF-Text bewerten').all().filter(it => it.json.needs_ocr);
const all = $input.all();
const out = [];
for (let i = 0; i < all.length; i++) {
  const buf = await this.helpers.getBinaryDataBuffer(i, 'data');
  const b = all[i].binary && all[i].binary.data;
  const mime = (b && b.mimeType) || 'image/png';
  const dataUrl = 'data:' + mime + ';base64,' + buf.toString('base64');
  const src = sources[i] || { json: {} };
  out.push({ json: {
    pdf_index: src.json.pdf_index != null ? src.json.pdf_index : i,
    pdf_name: src.json.pdf_name || ('Dokument_' + (i + 1)),
    requestBody: {
      model: cfg.vlm_model, temperature: 0, max_tokens: 2000, stream: false,
      messages: [
        { role: 'system', content: 'Du bist ein praeziser OCR-Assistent. Gib den gesamten lesbaren Text des Dokumentbildes woertlich und vollstaendig zurueck, ohne Kommentar, ohne Markdown.' },
        { role: 'user', content: [
          { type: 'text', text: 'Extrahiere den gesamten Text aus diesem Dokumentbild woertlich.' },
          { type: 'image_url', image_url: { url: dataUrl } }
        ] }
      ]
    }
  } });
}
return out;

// Vision-Antworten -> {pdf_index, pdf_name, text}.
const prompts = $('Vision-OCR Prompt').all();
const res = $input.all();
return res.map((it, i) => {
  const j = it.json; let c = '';
  if (j && j.choices && j.choices[0] && j.choices[0].message) c = j.choices[0].message.content || '';
  c = String(c).replace(/<think>[\s\S]*?<\/think>/g, '').trim();
  const p = prompts[i] ? prompts[i].json : {};
  return { json: { pdf_index: p.pdf_index != null ? p.pdf_index : i, pdf_name: p.pdf_name || ('Dokument_' + (i + 1)), text: c } };
});

